DROP TABLE IF EXISTS `layanans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `layanans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_id` int(11) NOT NULL,
  `sub_category_id` int(11) NOT NULL DEFAULT '0',
  `layanan` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `harga` int(11) NOT NULL,
  `harga_reseller` int(11) NOT NULL,
  `harga_platinum` int(11) NOT NULL,
  `harga_gold` int(11) NOT NULL,
  `harga_flash_sale` int(11) DEFAULT '0',
  `profit` int(11) NOT NULL,
  `profit_reseller` int(11) NOT NULL,
  `profit_platinum` int(11) NOT NULL,
  `profit_gold` int(11) NOT NULL,
  `is_flash_sale` tinyint(1) NOT NULL,
  `judul_flash_sale` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `banner_flash_sale` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expired_flash_sale` date DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint(1) NOT NULL,
  `provider` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `product_logo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `layanans_status_is_flash_sale_idx` (`status`,`is_flash_sale`),
  KEY `layanans_kategori_id_status_idx` (`kategori_id`,`status`),
  KEY `layanans_sub_category_id_status_idx` (`sub_category_id`,`status`),
  KEY `layanans_provider_id_status_idx` (`provider_id`,`status`),
  KEY `layanans_is_flash_sale_expired_flash_sale_idx` (`is_flash_sale`,`expired_flash_sale`)
) ENGINE=InnoDB AUTO_INCREMENT=733 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

