  `harga` int(11) NOT NULL,
  `profit` int(11) NOT NULL,
  `provider_order_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `log` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sn` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipe_transaksi` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'game',
  `is_digi` tinyint(1) NOT NULL,
  `ref_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `success_report_sended` tinyint(1) NOT NULL,
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pembelians_order_id_key` (`order_id`),
  KEY `pembelians_order_id_username_status_idx` (`order_id`,`username`,`status`),
  KEY `pembelians_order_id_status_idx` (`order_id`,`status`),
  KEY `pembelians_username_created_at_idx` (`username`,`created_at`),
  KEY `pembelians_status_created_at_idx` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=1930 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
